import re
def show(path, lines, ctx=6):
    src=open(path,errors='replace').read().split('\n')
    heads=[(i+1,l) for i,l in enumerate(src) if l and re.match(r'^[A-Za-z_]',l) and '(' in l]
    print("="*20,path)
    for tl in lines:
        enc=None
        for (ln,l) in heads:
            if ln<tl: enc=(ln,l)
            else: break
        print(f"[{tl}] in {enc[1][:90] if enc else '?'} ({enc[0] if enc else '?'})")
        for j in range(max(0,tl-2),min(len(src),tl+2)):
            print(f"  {j+1}: {src[j][:110]}")

